-- ============================================================================
-- v1395: Seed / sample data — Cutover registers (v1394) for the demo project
-- ============================================================================
-- Owner request 2026-11-09: sample data where it was missing, for SEED334-PRJ-08 (fictional
-- "Northbridge Bank" core banking replacement, go-live weekend 9–12 April 2027, dress rehearsals
-- 13 Feb, 6 Mar and 20 Mar 2027 — the same scenario as the Data Migration, Testing and Runbook samples).
--   * Cutover Activities, Dependencies, Command Centre, Go / No-Go, Communications, Business Readiness,
--     Technology Readiness and Cutover Sign-Off: 10 records each.
--   * Cutover Strategy, Cutover Plan and Rollback Plan: one complete document each — a document
--     register holds one current document per project (versions are kept in its Version History),
--     as with the Data Migration, Testing and Dress Rehearsal Strategy samples. All three are Draft:
--     on a document register only the Sign-off tab sets In Review and Approved (v1318), so a
--     seed cannot set them — approve the strategy through its Sign-off tab.
-- Dated around today (9 Nov 2026): the mock migrations (Sep–Oct 2026) carry real command-centre
-- entries, go/no-go decisions and sign-offs, preparation work is under way, and
-- everything for the rehearsals and the go-live weekend is planned. Calculated fields (durations,
-- time to resolve, delivery rate, training completion) are worked out with the same rules as the app.
-- Records: strategy 1, plan 1, activities 10, dependencies 10, command 10, gonogo 10, rollback 1, comms 10, business 10, technology 10, signoff 10.
-- Vendor-neutral (rule 26), person fields are plain text. display_id is left blank so Admin ID Generation
-- assigns it (rule 16.2). Fixed hex-only ids …-4000-b01e- … b028- (ranges checked free before use).
-- ON CONFLICT (id) DO NOTHING, and nothing is inserted if the project is missing. The final query counts the
-- records per register, so a skipped insert is visible.
-- Generated and validated against the field definitions (every option, column and date checked).
-- Prerequisites: v1394. Idempotent.
-- ============================================================================

INSERT INTO public.local_register_records
  (id, register_id, display_id, title, description, status, field_values, account_id, project_id, record_project_id)
SELECT v.id::uuid, v.register_id::uuid, '', v.title, v.description, v.status, v.vals::jsonb, p.account_id, p.id, p.id
FROM (VALUES
  ('00000000-0000-4000-b01e-000000000001', '00000000-0000-4000-9001-00000000001e', 'Cutover Strategy – Core Banking Replacement (Release 1)', 'How Northbridge Bank moves from the legacy core banking system to the new platform over the go-live weekend.', 'draft', $j${"document_reference":"CUT-STR-001","document_version":"1.2","document_owner":"Daniel Okafor","next_review_date":"2027-01-15","cutover_approach":"big_bang","target_go_live_date":"2027-04-12","cutover_window_start":"2027-04-09","cutover_window_end":"2027-04-12","purpose":"To set out how the bank moves every product, customer and balance from the legacy core banking system to the new platform in one controlled weekend, with clear decision points and a tested route back.","objectives":"Go live on Monday 12 April 2027 with all Release 1 products\nKeep customer-facing downtime inside the agreed window\nReconcile every migrated balance to zero unexplained differences\nKeep a tested rollback available until the point of no return\nOpen branches and digital channels on time on Monday","scope":"Final data migration (static and financial windows)\nTechnical cutover of interfaces and channels\nBusiness verification and reconciliation\nGo/no-go governance and the command centre\nCustomer, staff and regulator communications","out_of_scope":"Release 2 products (wealth and insurance)\nDecommissioning the legacy system (separate project)\nHypercare beyond the first two weeks","assumptions":"Mock 3 and three dress rehearsals complete before go-live\nThe regulator has no objection to the cutover date\nThird-party payment schemes support the switch-over weekend","constraints":"Cutover only over a weekend outside month-end and public holidays\nCard and ATM services may be down for no more than 4 hours\nRegulatory returns for March must be submitted from the legacy system","approach_description":"A single big-bang weekend. Business freezes at close of business on Friday, final data is extracted and migrated in two windows (static, then financial), interfaces are switched, and the business verifies results before the final go/no-go on Sunday evening. Digital channels reopen in stages from Sunday night, branches open on Monday.","cutover_phases":["preparation","freeze","final_migration","technical_cutover","business_validation","go_no_go","go_live","hypercare"],"key_milestones":"Cutover strategy approved\t2026-10-30\tDaniel Okafor\nCutover plan baselined\t2027-01-29\tFatima Bello\nDress rehearsal 1\t2027-02-13\tFatima Bello\nDress rehearsal 2\t2027-03-06\tFatima Bello\nDress rehearsal 3 (final timed)\t2027-03-20\tFatima Bello\nGo-live approval by the board\t2027-04-06\tGrace Moyo\nGo-live\t2027-04-12\tDaniel Okafor","dependencies":"Mock 3 reconciled and signed off\nPayment scheme switch-over windows confirmed\nProduction and DR environments certified\nStaff trained and rostered for the weekend","code_freeze_date":"2027-03-26","data_freeze_date":"2027-04-09","business_freeze_rules":"No new products or tariff changes from 26 March 2027\nNo static data changes in the legacy system after 18:00 on Friday 9 April\nBack-valued transactions only with cutover manager approval\nMonth-end processing for March completed on the legacy system","planned_downtime":36,"services_and_channels_impacted":"Internet and mobile banking\tRead-only, then unavailable\tFri 18:00 to Sun 21:00\nCards and ATMs\tStand-in authorisation with lower limits\tUp to 4 hours on Saturday night\nBranch systems\tBranches closed\tSaturday\nOutgoing payments\tHeld, released in priority order\tFri 18:00 to Sun 19:00","fallback_manual_procedures":"Card authorisation stand-in limits during the downtime\nContact centre scripts for balance enquiries\nManual high-value payment approvals by treasury","customer_communication_required":true,"go_no_go_criteria":"No open critical defects\nReconciliation balanced or differences explained and accepted\nSchedule within 2 hours of plan\nBusiness verification signed off by every unit\nRollback still possible within the window","decision_points":"Friday 16:00\tFreeze go/no-go\tProgramme director\nSaturday 06:00\tStatic window complete\tCutover manager\nSaturday 22:00\tFinancial migration complete\tCutover manager\nSunday 12:00\tReconciliation and business verification\tCutover board\nSunday 18:00\tFinal go-live decision (point of no return)\tExecutive sponsor","command_centre_arrangements":"The command centre runs from the head office operations room from Friday 14:00 to Monday 12:00, with a bridge line for remote teams. Shift leads hand over every 12 hours, status updates go out every 2 hours.","escalation_path":"Workstream lead\tWithin 15 minutes\nCutover manager\tWithin 30 minutes\nCutover board (programme director chair)\tGo/no-go questions or schedule slips over 1 hour\nExecutive sponsor\tRollback decisions","rollback_triggers":"Reconciliation differences that cannot be explained by Sunday 12:00\nA critical defect with no fix or workaround\nSchedule slip that pushes go-live past Monday 05:00\nFailure of payment scheme connectivity","point_of_no_return":"Sunday 11 April 2027 at 18:00, once outgoing payments are released from the new platform. After this point the bank fixes forward.","rollback_approach":"Restore the legacy system from the Friday close-of-business backup, re-point interfaces and channels, and replay transactions captured during the freeze. See the Rollback Plan (RB-PLN-001).","risks_mitigations":"Migration overruns the financial window\tGo-live delayed\tTimed dress rehearsals, parallel loads where safe, 4-hour contingency\tFatima Bello\nPayment scheme switch fails\tPayments not processed on Monday\tScheme test on dress rehearsal 3, vendor engineer on site\tAhmed Hassan\nKey staff unavailable\tSteps not done on time\tNamed back-ups for every role on the roster\tJoy Akinyi\nCustomer confusion about downtime\tContact centre overload\tAdvance notices from 4 weeks before, extra contact centre staff\tLinda Zhou","roles_and_responsibilities":"Executive sponsor\tFinal rollback authority\tGrace Moyo\nProgramme director\tChairs the cutover board and go/no-go decisions\tDaniel Okafor\nCutover manager\tRuns the cutover plan and command centre\tFatima Bello\nData migration lead\tRuns the migration windows and reconciliation\tKwame Asante\nTechnical lead\tInfrastructure, interfaces and channels\tAhmed Hassan\nBusiness readiness lead\tBusiness verification and branch opening\tAmina Diallo","glossary":"Cutover\tThe move from the legacy core banking system to the new platform, from business freeze to go-live.\nCommand centre\tThe room and bridge line where the cutover is run, monitored and decided.\nGo/No-Go\tA formal checkpoint where the cutover board decides to continue, pause or roll back.\nPoint of no return\tThe last moment a rollback to the legacy system is possible without unacceptable data loss.\nDress rehearsal\tA full, timed run of the cutover in pre-production using the go-live runbook.\nHypercare\tThe period of heightened support after go-live.","appendices":"Cutover Plan\tCUT-PLN-001\nRollback Plan\tRB-PLN-001\nData Migration Strategy\tDM-STR-001\nDress Rehearsal Strategy\tDR-STR-001","version_history":"0.1\t2026-08-14\tFatima Bello\tFirst draft\n1.0\t2026-10-30\tDaniel Okafor\tApproved by the cutover board\n1.1\t2026-11-03\tFatima Bello\tDecision point times updated after Mock 2\n1.2\t2026-11-09\tFatima Bello\tCard downtime limit agreed with card operations","related_documents":"Data Migration Strategy\tDM-STR-001\nTesting Strategy\tTS-STR-001\nDress Rehearsal Strategy\tDR-STR-001\nHypercare Plan\t"}$j$),
  ('00000000-0000-4000-b01f-000000000001', '00000000-0000-4000-9001-00000000001f', 'Cutover Plan – Go-Live Weekend (9–12 April 2027)', 'Hour-by-hour plan for the go-live weekend: activities, checkpoints, communications and contacts.', 'draft', $j${"document_reference":"CUT-PLN-001","document_version":"0.4","document_owner":"Fatima Bello","next_review_date":"2027-01-29","cutover_manager":"Fatima Bello","cutover_start":"2027-04-09","cutover_end":"2027-04-12","planned_go_live_date":"2027-04-12","purpose":"To give every team the exact sequence, timing and owner of each activity on the go-live weekend, with the checkpoints at which the cutover board decides to continue.","objectives":"Complete every cutover activity inside the weekend window\nHit each go/no-go checkpoint on time\nKeep all teams informed through the command centre","scope":"All activities from business freeze to branch opening\nData migration windows 1 and 2\nInterface and channel switch-over\nBusiness verification","out_of_scope":"Pre-cutover preparation tracked in Cutover Activities before 9 April\nHypercare activities after Monday 12:00","assumptions":"Dress rehearsal 3 timings hold within 10%\nAll runbook owners are rostered for their shifts","constraints":"Branches must open at 08:00 on Monday\nCard downtime limited to 4 hours","cutover_phases":["freeze","final_migration","technical_cutover","business_validation","go_no_go","go_live"],"activity_runsheet":"1\tBusiness freeze and end-of-day on legacy\tOperations\tFri 18:00\t2h\n2\tLegacy backup and extract\tInfrastructure\tFri 20:00\t3h\n3\tStatic data migration (window 1)\tData migration\tSat 00:00\t6h\n4\tFinancial data migration (window 2)\tData migration\tSat 08:00\t14h\n5\tInterface and channel switch-over\tIntegration\tSat 22:00\t6h\n6\tReconciliation and business verification\tBusiness\tSun 04:00\t8h\n7\tFinal go-live decision\tCutover board\tSun 18:00\t1h\n8\tRelease payments and open digital channels\tPayments / Digital\tSun 19:00\t4h\n9\tBranch opening checks\tBranches\tMon 06:00\t2h","critical_path":"Legacy backup and extract\nFinancial data migration\nReconciliation\nFinal go-live decision","checkpoints":"Freeze go/no-go\tFri 16:00\tProgramme director\nStatic window complete\tSat 06:00\tCutover manager\nFinancial migration complete\tSat 22:00\tCutover manager\nReconciliation and verification\tSun 12:00\tCutover board\nFinal go-live (point of no return)\tSun 18:00\tCutover board","entry_criteria":"Dress rehearsal 3 signed off\nGo-live approved by the board\nAll business and technology readiness assessments green or accepted","technical_prerequisites":"Production environment certified\nLegacy backup verified the day before\nScheme connectivity tested","business_prerequisites":"Freeze notices issued to all units\nVerification testers rostered\nContact centre scripts in place","communication_schedule":"T-28 days\tCustomers\tPlanned service change notice\tEmail, SMS, website\nT-7 days\tAll staff\tCutover weekend instructions\tIntranet\nFri 18:00\tCustomers\tServices paused\tSMS, website\nEvery 2 hours\tCutover teams\tStatus update\tBridge line, email\nMon 06:00\tCustomers and staff\tServices restored\tSMS, website, intranet","stakeholders_to_notify":"Executive committee\nRegulator (banking supervision)\nPayment scheme operators\nCorrespondent banks\nAll staff","contact_list":"Fatima Bello\tCutover manager\t+000 700 100 001\nDaniel Okafor\tProgramme director\t+000 700 100 002\nKwame Asante\tData migration lead\t+000 700 100 003\nAhmed Hassan\tTechnical lead\t+000 700 100 004\nAmina Diallo\tBusiness readiness lead\t+000 700 100 005","validation_checks":"Record counts per data set match the extract\nGeneral ledger balances agree by branch and currency\nSample customer and account checks by each business unit\nEnd-to-end payment, card and channel transactions","exit_criteria":"All runsheet activities complete or formally deferred\nGo-live approved at the final checkpoint\nHypercare team in place","rollback_triggers":"Unexplained reconciliation differences at Sun 12:00\nCritical defect without workaround\nSchedule slip beyond Mon 05:00","rollback_steps":"Follow the Rollback Plan (RB-PLN-001)","point_of_no_return":"Sunday 18:00 – release of payments from the new platform","risks_mitigations":"Financial window overruns\tLate go-live\tRun balance-sheet and product loads in parallel where safe\tKwame Asante\nInterface switch-over fails\tChannels not available\tSwitch-over rehearsed in all three dress rehearsals\tAhmed Hassan","roles_and_responsibilities":"Cutover manager\tRuns the runsheet and command centre\tFatima Bello\nShift lead (night)\tRuns the command centre overnight\tRavi Pillai\nBusiness verification lead\tCoordinates verification testers\tAmina Diallo","glossary":"Cutover\tThe move from the legacy core banking system to the new platform, from business freeze to go-live.\nCommand centre\tThe room and bridge line where the cutover is run, monitored and decided.\nGo/No-Go\tA formal checkpoint where the cutover board decides to continue, pause or roll back.\nPoint of no return\tThe last moment a rollback to the legacy system is possible without unacceptable data loss.\nDress rehearsal\tA full, timed run of the cutover in pre-production using the go-live runbook.\nHypercare\tThe period of heightened support after go-live.","appendices":"Cutover Strategy\tCUT-STR-001\nRollback Plan\tRB-PLN-001\nMigration Runbook – go-live\tMigration Runbook register","version_history":"0.1\t2026-09-20\tFatima Bello\tFirst draft from Mock 1 timings\n0.3\t2026-10-28\tFatima Bello\tRunsheet updated with Mock 2 timings\n0.4\t2026-11-09\tFatima Bello\tCheckpoints aligned with the approved strategy","related_documents":"Cutover Strategy\tCUT-STR-001\nRollback Plan\tRB-PLN-001"}$j$),
  ('00000000-0000-4000-b020-000000000001', '00000000-0000-4000-9001-000000000020', 'Confirm cutover roster and shift handovers', 'Every role on the go-live weekend has a named person and back-up, with 12-hour shifts.', 'in_progress', $j${"activity_reference":"CA-001","cutover_event":"go_live","cutover_phase":"preparation","sequence":1,"activity_type":"governance","owner":"Joy Akinyi","team":"Cutover office","planned_start":"2027-03-22T08:00:00.000Z","planned_end":"2027-03-26T17:00:00.000Z","critical_path":false,"can_run_in_parallel":true,"actual_start":"2026-11-02T09:00:00.000Z","instructions":"Collect names and back-ups from each workstream lead, publish the roster on the intranet and in the command centre.","successors":"Cutover weekend briefing","notes":"Started early: workstream leads asked for the roster template in November.","planned_minutes":6300}$j$),
  ('00000000-0000-4000-b020-000000000002', '00000000-0000-4000-9001-000000000020', 'Production environment certification', 'Infrastructure, security and performance certification of production and DR.', 'in_progress', $j${"activity_reference":"CA-002","cutover_event":"go_live","cutover_phase":"preparation","sequence":2,"activity_type":"technical","owner":"Ahmed Hassan","team":"Infrastructure","planned_start":"2027-03-01T08:00:00.000Z","planned_end":"2027-03-19T17:00:00.000Z","critical_path":true,"actual_start":"2026-11-04T08:00:00.000Z","systems_involved":"Core banking production\nDR site\nIntegration layer","successors":"Dress rehearsal 3\nGo-live approval","issues":"DR storage replication lag\tFailover time above target\tStorage vendor tuning\tAhmed Hassan","planned_minutes":26460}$j$),
  ('00000000-0000-4000-b020-000000000003', '00000000-0000-4000-9001-000000000020', 'Business freeze and legacy end of day', 'Stop business changes and run the final end of day on the legacy system.', 'not_started', $j${"activity_reference":"CA-003","cutover_event":"go_live","cutover_phase":"freeze","sequence":3,"activity_type":"business","owner":"Amina Diallo","team":"Operations","planned_start":"2027-04-09T18:00:00.000Z","planned_end":"2027-04-09T20:00:00.000Z","critical_path":true,"systems_involved":"Legacy core banking","predecessors":"Freeze go/no-go (Fri 16:00)","successors":"Legacy backup and extract","instructions":"Confirm all branches closed, run end of day, confirm EOD reports balanced.","planned_minutes":120}$j$),
  ('00000000-0000-4000-b020-000000000004', '00000000-0000-4000-9001-000000000020', 'Legacy backup and final extract', 'Full verified backup of the legacy database and extract of all migration data sets.', 'not_started', $j${"activity_reference":"CA-004","cutover_event":"go_live","cutover_phase":"final_migration","sequence":4,"activity_type":"technical","owner":"Ahmed Hassan","team":"Infrastructure","planned_start":"2027-04-09T20:00:00.000Z","planned_end":"2027-04-09T23:00:00.000Z","critical_path":true,"predecessors":"Business freeze and legacy end of day","successors":"Static data migration","completion_evidence":"Backup verification report","systems_involved":"Legacy core banking\nBackup platform","planned_minutes":180}$j$),
  ('00000000-0000-4000-b020-000000000005', '00000000-0000-4000-9001-000000000020', 'Static data migration (window 1)', 'Customers, accounts and static details loaded onto the new platform.', 'not_started', $j${"activity_reference":"CA-005","cutover_event":"go_live","cutover_phase":"final_migration","sequence":5,"activity_type":"data_migration","owner":"Kwame Asante","team":"Data migration","planned_start":"2027-04-10T00:00:00.000Z","planned_end":"2027-04-10T06:00:00.000Z","critical_path":true,"predecessors":"Legacy backup and final extract","successors":"Financial data migration","instructions":"Follow the go-live Migration Runbook, static window steps.","planned_minutes":360}$j$),
  ('00000000-0000-4000-b020-000000000006', '00000000-0000-4000-9001-000000000020', 'Financial data migration (window 2)', 'Balances, loans, deposits, trade finance and the general ledger loaded in batches.', 'not_started', $j${"activity_reference":"CA-006","cutover_event":"go_live","cutover_phase":"final_migration","sequence":6,"activity_type":"data_migration","owner":"Kwame Asante","team":"Data migration","planned_start":"2027-04-10T08:00:00.000Z","planned_end":"2027-04-10T22:00:00.000Z","critical_path":true,"predecessors":"Static data migration (window 1)","successors":"Reconciliation and business verification","planned_minutes":840}$j$),
  ('00000000-0000-4000-b020-000000000007', '00000000-0000-4000-9001-000000000020', 'Interface and channel switch-over', 'Re-point payment schemes, card switch, internet and mobile banking to the new platform.', 'not_started', $j${"activity_reference":"CA-007","cutover_event":"go_live","cutover_phase":"technical_cutover","sequence":7,"activity_type":"technical","owner":"Ahmed Hassan","team":"Integration","planned_start":"2027-04-10T22:00:00.000Z","planned_end":"2027-04-11T04:00:00.000Z","critical_path":false,"can_run_in_parallel":true,"systems_involved":"Integration layer\nCard switch\nPayment scheme gateways\nDigital banking","predecessors":"Static data migration (window 1)","planned_minutes":360}$j$),
  ('00000000-0000-4000-b020-000000000008', '00000000-0000-4000-9001-000000000020', 'Reconciliation and business verification', 'Finance reconciles balances, each business unit verifies sample customers and accounts.', 'not_started', $j${"activity_reference":"CA-008","cutover_event":"go_live","cutover_phase":"business_validation","sequence":8,"activity_type":"validation","owner":"Olivia Banda","team":"Finance and business","planned_start":"2027-04-11T04:00:00.000Z","planned_end":"2027-04-11T12:00:00.000Z","critical_path":true,"predecessors":"Financial data migration (window 2)","successors":"Final go-live decision","planned_minutes":480}$j$),
  ('00000000-0000-4000-b020-000000000009', '00000000-0000-4000-9001-000000000020', 'Release payments and open digital channels', 'Release held payments and reopen internet and mobile banking in stages.', 'not_started', $j${"activity_reference":"CA-009","cutover_event":"go_live","cutover_phase":"go_live","sequence":9,"activity_type":"technical","owner":"Linda Zhou","team":"Payments and digital","planned_start":"2027-04-11T19:00:00.000Z","planned_end":"2027-04-11T23:00:00.000Z","critical_path":true,"predecessors":"Final go-live decision (Sun 18:00)","successors":"Branch opening checks","planned_minutes":240}$j$),
  ('00000000-0000-4000-b020-000000000010', '00000000-0000-4000-9001-000000000020', 'Branch opening checks', 'Every branch confirms systems, cash and teller access before opening on Monday.', 'not_started', $j${"activity_reference":"CA-010","cutover_event":"go_live","cutover_phase":"go_live","sequence":10,"activity_type":"business","owner":"Amina Diallo","team":"Branch network","planned_start":"2027-04-12T06:00:00.000Z","planned_end":"2027-04-12T08:00:00.000Z","critical_path":true,"predecessors":"Release payments and open digital channels","completion_evidence":"Branch opening checklist returned by all branches","planned_minutes":120}$j$),
  ('00000000-0000-4000-b021-000000000001', '00000000-0000-4000-9001-000000000021', 'Regulator no-objection to the go-live date', 'Banking supervision confirms no objection to cutover on 9–12 April 2027.', 'resolved', $j${"dependency_reference":"DEP-001","dependency_type":"regulatory","direction":"inbound","provider":"Banking supervisor","receiver":"Programme board","cutover_phase":"preparation","owner":"Nomvula Khumalo","criticality":"critical","needed_by_date":"2026-12-15","committed_date":"2026-10-28","rag_status":"green","confirmation_received":true,"confirmation_reference":"Letter ref. BS/2026/1184","impact_if_missed":"Go-live date cannot be confirmed.","progress_updates":"2026-10-07\tCutover strategy shared with the supervisor\tNomvula Khumalo\n2026-10-28\tNo-objection letter received\tNomvula Khumalo"}$j$),
  ('00000000-0000-4000-b021-000000000002', '00000000-0000-4000-9001-000000000021', 'Payment scheme switch-over window', 'Domestic payment scheme confirms the participant switch-over on Saturday 10 April.', 'open', $j${"dependency_reference":"DEP-002","dependency_type":"third_party","direction":"inbound","provider":"Domestic payment scheme operator","receiver":"Integration","cutover_phase":"technical_cutover","owner":"Linda Zhou","criticality":"critical","needed_by_date":"2027-02-01","committed_date":"2027-01-20","rag_status":"amber","impact_if_missed":"Outgoing and incoming payments cannot be processed on the new platform.","affected_activities":"Interface and channel switch-over\nRelease payments and open digital channels","workaround":"Route payments through the legacy gateway for up to 48 hours.","progress_updates":"2026-11-05\tRequest submitted, scheme asked for test evidence from SIT\tLinda Zhou"}$j$),
  ('00000000-0000-4000-b021-000000000003', '00000000-0000-4000-9001-000000000021', 'Card switch re-routing', 'Card processor re-routes BIN ranges to the new platform during the card downtime window.', 'open', $j${"dependency_reference":"DEP-003","dependency_type":"third_party","direction":"inbound","provider":"Card processor","receiver":"Card operations","cutover_phase":"technical_cutover","owner":"Ahmed Hassan","criticality":"critical","needed_by_date":"2027-03-01","rag_status":"amber","impact_if_missed":"Card authorisations fail after go-live.","affected_activities":"Interface and channel switch-over","workaround":"Extend stand-in processing with lower limits."}$j$),
  ('00000000-0000-4000-b021-000000000004', '00000000-0000-4000-9001-000000000021', 'Production environment certified', 'Infrastructure certifies production and DR before dress rehearsal 3.', 'open', $j${"dependency_reference":"DEP-004","dependency_type":"infrastructure","direction":"inbound","provider":"Infrastructure team","receiver":"Cutover office","cutover_phase":"preparation","owner":"Ahmed Hassan","criticality":"high","needed_by_date":"2027-03-19","committed_date":"2027-03-12","rag_status":"green","affected_activities":"Dress rehearsal 3\nGo-live"}$j$),
  ('00000000-0000-4000-b021-000000000005', '00000000-0000-4000-9001-000000000021', 'Mock 3 reconciliation sign-off', 'Finance and the business sign off the Mock 3 reconciliation before dress rehearsals.', 'open', $j${"dependency_reference":"DEP-005","dependency_type":"internal_business","direction":"inbound","provider":"Data migration workstream","receiver":"Cutover office","cutover_phase":"preparation","owner":"Kwame Asante","criticality":"high","needed_by_date":"2027-01-31","committed_date":"2027-01-29","rag_status":"green","impact_if_missed":"Dress rehearsal 1 starts without proven data."}$j$),
