-- Check: sample records per register (10 each, and 1 each for Cutover Strategy, Cutover Plan and Rollback Plan).
SELECT l.register_key, count(r.id) AS records
FROM public.local_registers l
LEFT JOIN public.local_register_records r ON r.register_id = l.id AND r.is_deleted = FALSE
WHERE l.id IN ('00000000-0000-4000-9001-00000000001e'::uuid, '00000000-0000-4000-9001-00000000001f'::uuid, '00000000-0000-4000-9001-000000000020'::uuid, '00000000-0000-4000-9001-000000000021'::uuid, '00000000-0000-4000-9001-000000000022'::uuid, '00000000-0000-4000-9001-000000000023'::uuid, '00000000-0000-4000-9001-000000000024'::uuid, '00000000-0000-4000-9001-000000000025'::uuid, '00000000-0000-4000-9001-000000000026'::uuid, '00000000-0000-4000-9001-000000000027'::uuid, '00000000-0000-4000-9001-000000000028'::uuid)
GROUP BY l.register_key ORDER BY l.register_key;
